WITH unpacked AS (SELECT id, service, level, latency_ms, payload_json, context, context['region'] AS region, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs) SELECT service, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN level = 'ERROR' THEN 1 END), 0), 2) AS latency_ms_per_error, COUNT_IF(service = 'search') AS search_events, SUM(latency_ms) FILTER (WHERE level = 'WARN') AS warn_total_latency_ms FROM unpacked GROUP BY 1 ORDER BY search_events NULLS FIRST;
